@TestOn('vm')
library;

import 'package:dev_build/package.dart';
import 'package:pubglobalupdate/src/dart_installed_package.dart';
import 'package:pubglobalupdate/src/io/git_lock_source.dart';
import 'package:pubglobalupdate/src/io/global_tool_package.dart';
import 'package:pubglobalupdate/src/tool.dart';
import 'package:test/test.dart';

/// Extract of a `pubspec.lock` of `dart install` or `dart pub global activate`.
const _lock = '''
# Generated by pub
packages:
  args:
    dependency: transitive
    description:
      name: args
      sha256: "d0481093c50b1da8910eb0bb301626d4d8eb7284aa739614d2b394ee09e3ea04"
      url: "https://pub.dev"
    source: hosted
    version: "2.7.0"
  my_tools:
    dependency: "direct main"
    description:
      path: "packages/my_tools"
      ref: HEAD
      resolved-ref: "4c7f13da02c76af4d35cdf411c6da01803a4d45c"
      url: "git@github.com:example/tools.dart.git"
    source: git
    version: "1.0.154"
  root_tool:
    dependency: "direct main"
    description:
      path: "."
      ref: dart3a
      resolved-ref: "682da018658686db035d31e12ba58545e2b62efe"
      url: "file:///repo/root_tool"
    source: git
    version: "0.2.0"
sdks:
  dart: ">=3.12.0 <4.0.0"
''';

void main() {
  group('git_lock_source', () {
    test('parseGitLockSource', () {
      var source = parseGitLockSource(_lock, 'my_tools')!;
      expect(source.url, 'git@github.com:example/tools.dart.git');
      expect(source.path, 'packages/my_tools');
      // HEAD is the default branch
      expect(source.ref, isNull);

      source = parseGitLockSource(_lock, 'root_tool')!;
      expect(source.url, 'file:///repo/root_tool');
      expect(source.path, isNull);
      expect(source.ref, 'dart3a');

      // hosted, missing, invalid
      expect(parseGitLockSource(_lock, 'args'), isNull);
      expect(parseGitLockSource(_lock, 'other'), isNull);
      expect(parseGitLockSource('', 'my_tools'), isNull);
      expect(parseGitLockSource('not: [yaml', 'my_tools'), isNull);
    });
    test('isSameGitUrl', () {
      expect(
        isSameGitUrl('git@github.com:a/b.git', 'git@github.com:a/b.git'),
        isTrue,
      );
      expect(isSameGitUrl('file:///repo/x.dart', '/repo/x.dart'), isTrue);
      expect(
        isSameGitUrl('git@github.com:a/b.git', 'git@github.com:a/c.git'),
        isFalse,
      );
    });
    test('installed git package args', () {
      var installed = DartInstalledPackage.fromListLine(
        'my_tools 1.0.154 from Git repository '
        '"git@github.com:example/tools.dart.git" at "4c7f13da"',
      )!;
      // Without lock: the repository root.
      var package = GlobalToolPackage.fromInstalled(installed);
      expect(package.gitPath, isNull);
      expect(package.updateArgs, [
        'my_tools@{git: {url: git@github.com:example/tools.dart.git}}',
      ]);

      package = GlobalToolPackage.fromInstalled(
        installed,
        gitLock: parseGitLockSource(_lock, 'my_tools'),
      );
      expect(package.gitPath, 'packages/my_tools');
      expect(
        package.updateArgs.single,
        'my_tools@{git: {url: git@github.com:example/tools.dart.git, '
        'path: packages/my_tools}}',
      );
      expect(package.otherToolArgs, [
        '--source',
        'git',
        'git@github.com:example/tools.dart.git',
        '--git-path',
        'packages/my_tools',
      ]);
      expect(
        package.toString(),
        'my_tools 1.0.154 (install, git git@github.com:example/tools.dart.git '
        'path packages/my_tools)',
      );

      // Lock of another url ignored.
      package = GlobalToolPackage.fromInstalled(
        installed,
        gitLock: GitLockSource(url: 'git@github.com:other/x.git', path: 'x'),
      );
      expect(package.gitPath, isNull);
    });
    test('pub global git package args', () {
      var pubGlobal = PubGlobalPackage.fromListLine(
        'root_tool 0.2.0 from Git repository "/repo/root_tool"',
      )!;
      var package = GlobalToolPackage.fromPubGlobal(
        pubGlobal,
        gitLock: parseGitLockSource(_lock, 'root_tool'),
      );
      expect(package.tool, PubGlobalTool.activate);
      expect(package.gitPath, isNull);
      expect(package.gitRef, 'dart3a');
      expect(package.updateArgs, [
        '--source',
        'git',
        '/repo/root_tool',
        '--git-ref',
        'dart3a',
      ]);
      expect(package.otherToolArgs, [
        'root_tool@{git: {url: /repo/root_tool, ref: dart3a}}',
      ]);
    });
    test('hosted and path args', () {
      var hosted = GlobalToolPackage.fromInstalled(
        DartInstalledPackage.fromListLine('webdev 4.0.3')!,
      );
      expect(hosted.updateArgs, ['webdev']);
      expect(hosted.otherToolArgs, ['webdev']);
      var path = GlobalToolPackage.fromPubGlobal(
        PubGlobalPackage.fromListLine('tool 1.0.0 at path "/p/tool"')!,
      );
      expect(path.updateArgs, ['--source', 'path', '/p/tool']);
      expect(path.otherToolArgs, ['tool@{path: /p/tool}']);
    });
  });
}
